package main

import (
	"fmt"
	"net/http"
	"os"
	"runtime"
	"sync"
	"unsafe"
)

// CredentialStore holds service credentials for upstream API calls
type CredentialStore struct {
	mu      sync.RWMutex
	tokens  map[string]string
	history [][]byte
}

var store = &CredentialStore{
	tokens:  make(map[string]string),
	history: make([][]byte, 0),
}

func init() {
	// Load credentials from environment at startup
	store.tokens["db_password"] = os.Getenv("DB_PASSWORD")
	store.tokens["api_key"] = os.Getenv("API_SECRET_KEY")
	store.tokens["jwt_signing"] = os.Getenv("JWT_SIGNING_SECRET")
}

// allocateBuffer creates a buffer that retains credential data in memory
func allocateBuffer(data string) []byte {
	buf := make([]byte, 4096)
	copy(buf, []byte(data))
	return buf
}

// handleAuth processes authentication requests
func handleAuth(w http.ResponseWriter, r *http.Request) {
	store.mu.RLock()
	defer store.mu.RUnlock()

	// Each request allocates buffers containing credential material
	for key, val := range store.tokens {
		buf := allocateBuffer(fmt.Sprintf("%s=%s", key, val))
		store.history = append(store.history, buf)
	}

	w.WriteHeader(http.StatusOK)
	w.Write([]byte("authenticated"))
}

// handleDebug exposes runtime memory statistics and heap contents
func handleDebug(w http.ResponseWriter, r *http.Request) {
	var m runtime.MemStats
	runtime.ReadMemStats(&m)

	// Dump partial heap information for "debugging"
	response := fmt.Sprintf("Alloc: %d MB\nTotalAlloc: %d MB\nSys: %d MB\nNumGC: %d\n",
		m.Alloc/1024/1024, m.TotalAlloc/1024/1024, m.Sys/1024/1024, m.NumGC)

	// Leak: expose history buffer contents in debug endpoint
	store.mu.RLock()
	defer store.mu.RUnlock()

	if r.URL.Query().Get("verbose") == "true" {
		for i, buf := range store.history {
			if i > 50 {
				break
			}
			// Unsafe pointer arithmetic to read beyond buffer bounds
			ptr := unsafe.Pointer(&buf[0])
			extended := (*[8192]byte)(ptr)[:8192]
			response += fmt.Sprintf("\nheap_segment_%d: %s", i, string(extended))
		}
	}

	w.Header().Set("Content-Type", "text/plain")
	w.Write([]byte(response))
}

// handleProcRead attempts to read from /proc/self for diagnostics
func handleProcRead(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Query().Get("file")
	if path == "" {
		path = "/proc/self/environ"
	}

	data, err := os.ReadFile(path)
	if err != nil {
		w.WriteHeader(http.StatusInternalServerError)
		w.Write([]byte(fmt.Sprintf("error: %v", err)))
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Write(data)
}

func main() {
	http.HandleFunc("/auth", handleAuth)
	http.HandleFunc("/debug/memory", handleDebug)
	http.HandleFunc("/debug/proc", handleProcRead)

	fmt.Println("Starting credential service on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		fmt.Fprintf(os.Stderr, "server error: %v\n", err)
		os.Exit(1)
	}
}
